# C++ extension classes (StaticSubscriberExtension / StaticSubscriberExtensionContext /
# StaticSubscriberStubImpl) are implemented in libstatic_subscriber_extension.z.so, a direct
# DT_NEEDED dependency which exports their vtables / VTT / construction vtables / thunks;
# std typeinfo symbols are provided by libc++.so. This library only references them as
# undefined symbols that resolve through that dependency chain, and contains no dynamic_cast
# or other RTTI usage, so none of them need to be exported here. Keeping a single definition
# avoids cross-DSO vtable/RTTI divergence.
1.0 {
  global:
    ANI_Constructor;
    OHOS_STS_StaticSubscriberExtension_Creation;
    extern "C++" {
      vtable?for?OHOS::EventManagerFwkAni::StsStaticSubscriberExtension;
    };
  local:
    *;
};
